/**
 * teaser — the 20-second AnyRouter brand film, in two themes from one source.
 *
 * AUTHORED, not generated by lib/film.mjs: it has its own generator in
 * release/generate.mjs, which writes index.html + compositions/ for one theme.
 * The committed index.html is the light theme, and that is what the driver
 * renders. `node videos/teaser/tools/build.mjs` builds both themes.
 *
 * Rendered on demand (`node lib/cli.mjs run teaser`), never by the nightly run.
 */
import { collectAuthored } from '../../lib/authored.mjs';

const INPUTS = ['index.html', 'fonts', 'assets', 'audio/score.wav', 'compositions'];

export default {
  id: 'teaser',
  title: 'Teaser',
  scheduled: false,
  // its generator lays out 1920x1080 only (s11-pool's viewBox); portrait.mjs refuses it.
  renditions: ['landscape'],

  collect: ({ dir }) => collectAuthored(dir, INPUTS),

  headline: data => `AnyRouter in ${data.seconds} seconds`,

  notes: data => [
    `A ${data.seconds}-second brand film for AnyRouter: one OpenAI-compatible endpoint, one key, the model catalog, the free tier and the shared key pool.`,
    `Film version v${data.version}.`,
  ],

  /** The end card: domain, the three stats and the install command. */
  coverAt: () => 18.6,
};
